"""invoice_core.py - the plumbing for Lab 5.3. You do not edit this file.

It loads the eight invoices and their labels, reads the two prompts, turns an invoice into the text the model reads,
checks that an answer has the right shape, and prints the grade table. The Claude call itself is in lab.py.
"""
import hashlib
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).parent
RESULTS = HERE / "results"

DECISIONS = ["pay", "hold", "reject", "escalate"]
ESCALATION_VALUE = 100_000  # USD. The same number is written in prompts/v2.txt.
CHECKS = ["schema", "decision", "items", "total", "escalate"]

INVOICES = {i["id"]: i for i in json.loads((HERE / "data" / "invoices.json").read_text(encoding="utf-8"))}
CASES = json.loads((HERE / "data" / "cases.json").read_text(encoding="utf-8"))


def prompt(version):
    """Read prompts/v1.txt or prompts/v2.txt."""
    return (HERE / "prompts" / f"{version}.txt").read_text(encoding="utf-8").strip()


def invoice_text(invoice):
    """The invoice as the model reads it: one line per line id."""
    lines = [f"Invoice {invoice['id']}: {invoice['title']} from {invoice['supplier']}"]
    lines += [f"Line {line['id']}: {line['text']}" for line in invoice["lines"]]
    return "\n".join(lines)


def parse_json(text):
    """Read the JSON object in a reply. Return None if there is none."""
    try:
        return json.loads(text[text.find("{"):text.rfind("}") + 1])
    except ValueError:
        return None


def schema_ok(output):
    """True if the answer has every key, with the right types and an allowed decision."""
    if not isinstance(output, dict):
        return False
    total, cited = output.get("total"), output.get("citations")
    return (output.get("decision") in DECISIONS
            and isinstance(output.get("escalate"), bool)
            and isinstance(total, (int, float)) and not isinstance(total, bool)
            and isinstance(output.get("explanation"), str)
            and isinstance(cited, list) and len(cited) > 0 and all(isinstance(item, str) for item in cited))


def load_run(version):
    """Read the saved run for one prompt version."""
    path = RESULTS / f"run_{version}.json"
    if not path.exists():
        sys.exit(f"No saved run for {version}. Run the earlier stage first (python lab.py --stage 1 for v1, --stage 3 for v2).")
    return json.loads(path.read_text(encoding="utf-8"))


def audit_record(record):
    """What was read, by which prompt and which model. Kept so an answer can be traced later."""
    text = invoice_text(INVOICES[record["case"]])
    return {"case": record["case"], "invoice_sha256": hashlib.sha256(text.encode()).hexdigest()[:16],
            "prompt_version": record["version"], "prompt_sha256": hashlib.sha256(prompt(record["version"]).encode()).hexdigest()[:16],
            "model": record["model"], "cited_items": record["output"]["citations"]}


def print_table(records, grades):
    """One row per case: the decision, the five checks and the verdict."""
    cases = {c["id"]: c for c in CASES}
    print(f"{'case':<5}{'expected':<10}{'got':<12}" + "".join(f"{name:<9}" for name in CHECKS) + "result")
    for record in records:
        output, checks = record["output"], grades[record["case"]]
        got = output["decision"] if schema_ok(output) else "(invalid)"
        print(f"{record['case']:<5}{cases[record['case']]['expected_decision']:<10}{got:<12}"
              + "".join(f"{'ok' if checks[name] else 'FAIL':<9}" for name in CHECKS) + ("PASS" if all(checks.values()) else "FAIL"))
